<?php require_once 'auth.php';requiereRol('cliente');$id=(int)$_SESSION['idUsuario'];$q=$conexion->prepare('SELECT idMascota,nombre FROM mascotas WHERE idUsuario=?');$q->execute([$id]);$pets=$q->fetchAll();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$mas=(int)($_POST['idMascota']??0);$fecha=$_POST['fecha_cita']??'';$hora=$_POST['hora']??'';$mot=trim($_POST['motivo']??'');$valid=$conexion->prepare('SELECT COUNT(*) FROM mascotas WHERE idMascota=? AND idUsuario=?');$valid->execute([$mas,$id]);if($valid->fetchColumn() && $fecha>=date('Y-m-d') && $hora && $mot){$q=$conexion->prepare("INSERT INTO citas(idUsuario,idMascota,fecha_cita,hora,motivo,estado) VALUES(?,?,?,?,?,'Pendiente')");$q->execute([$id,$mas,$fecha,$hora,$mot]);$msg='Solicitud enviada. Un empleado revisará tu cita.';}else $msg='Verifica los datos. Debes registrar una mascota antes de solicitar cita.';}encabezado('Solicitar una cita');alerta($msg);?><div class="form-card"><p>La cita quedará en estado <b>Pendiente</b> hasta que un empleado la acepte o rechace.</p><?php if(!$pets):?><p>Primero registra una mascota en <a href="mis_mascotas.php">Mis mascotas</a>.</p><?php else:?><form method="post" class="form-grid"><label>Mascota<select name="idMascota" required><?php foreach($pets as $p):?><option value="<?=$p['idMascota']?>"><?=e($p['nombre'])?></option><?php endforeach;?></select></label><label>Fecha<input type="date" name="fecha_cita" min="<?=date('Y-m-d')?>" required></label><label>Hora<input type="time" name="hora" required></label><label class="wide">Motivo de consulta<textarea name="motivo" required></textarea></label><button class="btn">Enviar solicitud</button></form><?php endif;?></div><?php pie();?>